# MCP tools over the Content Security Policy violations browsers report
# (generated by maquina:csp_reports).
#
# Admin only: a member's token neither sees nor reaches these tools. Read-only.
# Reported URLs are stored without query or fragment; the reporter's IP address
# is not returned.
module Mcp
  module Tools
    module CspReports
      ADMIN_ONLY = true
      WRITE_TOOLS = %w[].freeze

      MAX_LIMIT = 50
      MAX_DAYS = 30
      SCHEMA = "https://json-schema.org/draft/2020-12/schema"

      DEFINITIONS = [
        {
          name: "list_csp_reports",
          description: "Content Security Policy violations browsers reported, newest first. Each entry has " \
            "the directive that was violated, the blocked URI, the page (document URI), the source file " \
            "with line and column, the disposition (enforce or report), a code sample when the browser " \
            "sent one, the user agent and at (ISO 8601 UTC). Reports are kept for 30 days. Returns at " \
            "most 50 entries.",
          inputSchema: {
            "$schema": SCHEMA, type: "object",
            properties: {limit: {type: "integer", description: "Number of reports to return, 1-50. Default 20."}},
            required: [], additionalProperties: false
          },
          annotations: {readOnlyHint: true}
        },
        {
          name: "csp_report_summary",
          description: "Content Security Policy violations over the last days, grouped by directive, " \
            "blocked URI and page, most frequent first: one group per thing to fix, with its count and " \
            "last_seen (ISO 8601 UTC). Also returns the total number of reports in the window. Returns at " \
            "most 50 groups.",
          inputSchema: {
            "$schema": SCHEMA, type: "object",
            properties: {days: {type: "integer", description: "Window length in days, 1-30. Default 7."}},
            required: [], additionalProperties: false
          },
          annotations: {readOnlyHint: true}
        }
      ].freeze

      def self.list_csp_reports(scope:, limit: 20)
        reports = ::Security::CspViolation.recent.limit(limit.to_i.clamp(1, MAX_LIMIT)).map do |violation|
          {effective_directive: violation.effective_directive, blocked_uri: violation.blocked_uri,
           document_uri: violation.document_uri, source_file: violation.source_file,
           line_number: violation.line_number, column_number: violation.column_number,
           disposition: violation.disposition, sample: violation.sample, user_agent: violation.user_agent,
           at: violation.created_at.utc.iso8601}
        end

        {reports: reports}
      end

      def self.csp_report_summary(scope:, days: 7)
        days = days.to_i.clamp(1, MAX_DAYS)
        report = ::Security::CspViolationReport.new(window: days.days, limit: MAX_LIMIT)

        groups = report.top.map do |group|
          group.to_h.merge(last_seen: group.last_seen&.utc&.iso8601)
        end

        {days: days, total: report.total, groups: groups}
      end
    end
  end
end
